/**
 * Gabriel's CV, as published on the website. src/data/resume.json is generated by
 * `npm run sync-cv` from the CV selected in the private cv repository (JSON Resume
 * format, private fields already removed). Never edit the JSON by hand: change the
 * CV, then sync.
 */
import data from '../data/resume.json';
import type { TimelineEntry } from '../config/about';

interface Dated {
  startDate?: string;
  endDate?: string;
}

export interface ResumeData {
  basics: {
    name: string;
    label?: string;
    email?: string;
    url?: string;
    summary?: string;
    location?: { city?: string; countryCode?: string };
    profiles?: { network?: string; username?: string; url?: string }[];
  };
  work?: (Dated & { name: string; position: string; location?: string; summary?: string; highlights?: string[] })[];
  education?: (Dated & {
    institution: string;
    studyType?: string;
    area?: string;
    specialization?: string;
    notes?: string;
  })[];
  projects?: (Dated & { name: string; description?: string; url?: string; highlights?: string[] })[];
  publications?: { name: string; publisher?: string; releaseDate?: string; summary?: string; url?: string }[];
  skills?: { name: string; keywords?: string[] }[];
  languages?: { language: string; fluency?: string; notes?: string }[];
  interests?: { name: string }[];
}

export const resume = data as ResumeData;

const COUNTRIES: Record<string, string> = { ES: 'Spain' };
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/** "2025-12" → "Dec 2025", "2019" → "2019". */
export function formatDate(iso: string): string {
  const [year, month] = iso.split('-');
  return month ? `${MONTHS[Number(month) - 1]} ${year}` : year;
}

/** "Dec 2025 – Present", or "Feb 2026 – expected Jun 2027" for an end date still in the future. */
export function period({ startDate, endDate }: Dated, today = new Date()): string {
  const start = startDate ? formatDate(startDate) : '';
  if (!endDate) return `${start} – Present`;
  const future = new Date(`${endDate.length === 4 ? `${endDate}-12` : endDate.slice(0, 7)}-01`) > today;
  return `${start} – ${future ? 'expected ' : ''}${formatDate(endDate)}`;
}

export const location = [resume.basics.location?.city, COUNTRIES[resume.basics.location?.countryCode ?? '']]
  .filter(Boolean)
  .join(', ');

export const profileUrl = (network: string) =>
  resume.basics.profiles?.find((p) => p.network?.toLowerCase() === network.toLowerCase())?.url ?? null;

export const experience: TimelineEntry[] = (resume.work ?? []).map((job) => ({
  title: job.position,
  organisation: job.name,
  period: period(job),
  location: job.location,
  details: job.summary,
  highlights: job.highlights,
}));

export const education: TimelineEntry[] = (resume.education ?? []).map((study) => ({
  title: [study.studyType, study.area].filter(Boolean).join(' in '),
  organisation: study.institution,
  period: period(study),
  details: [study.specialization && `Specialisation: ${study.specialization}.`, study.notes].filter(Boolean).join(' '),
}));
